+static bool is_package(GList* sorted_filenames) {
+    const char* filename;
+
+    if (sorted_filenames == NULL || g_list_length(sorted_filenames) > 1) {
+        return false;
+    }
+
+    filename = get_basename((const char*)sorted_filenames->data);
+    return strrchr(filename, '.') == NULL;
+}
